package com.hostelcare.repository; import com.hostelcare.entity.*; import com.hostelcare.enums.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface ComplaintRepository extends JpaRepository<Complaint,Long> { List<Complaint> findByStudentUserIdOrderByCreatedAtDesc(Long id); @Query("select c from Complaint c where exists (select a from Assignment a where a.complaint=c and a.staff.userId=:staff and a.active=true) order by c.createdAt desc") List<Complaint> findAssigned(@Param("staff") Long staff); @Query("select count(c) from Complaint c where c.status=:status") long countByStatus(@Param("status") ComplaintStatus status); List<Complaint> findAllByOrderByCreatedAtDesc(); }
